// Kids illustration system — flat-color, friendly geometric SVGs
// Palette: matches kids mode (warm oranges, gold, soft blues, cream)
// Style: flat shapes, no fine line work, intentional negative space.
// Each illustration is 240×140 to match the kids-illustration container.

// Shared palette
const PAL = {
  sun: "#e8b144",
  sunDark: "#c98a1a",
  orange: "#d97a4a",
  orangeDark: "#a85a30",
  brown: "#7a3a1a",
  brownDeep: "#4a2210",
  cream: "#fffaf0",
  sky: "#7ab4d4",
  skyDark: "#3a7a9a",
  mint: "#8aaa6a",
  mintDark: "#5a7a4a",
  rose: "#c46e72",
  plum: "#8a6db0",
  gold: "#f0c878",
};

// Frame wrapper — consistent inner padding + soft inner shadow
const Frame = ({ children, bg }) => (
  <svg viewBox="0 0 240 140" width="100%" height="100%" preserveAspectRatio="xMidYMid meet" style={{display:'block'}}>
    <defs>
      <linearGradient id="frameBg" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={bg?.[0] || "#ffe2b0"} />
        <stop offset="100%" stopColor={bg?.[1] || "#ffc878"} />
      </linearGradient>
    </defs>
    {children}
  </svg>
);

// 1:1 — Moshe at Sinai (mountain + Torah scroll + sun)
const IllSinai = () => (
  <Frame>
    {/* Sun */}
    <circle cx="200" cy="35" r="18" fill={PAL.sun} />
    <circle cx="200" cy="35" r="11" fill={PAL.gold} />
    {/* Mountain (back) */}
    <path d="M 110 130 L 170 60 L 240 130 Z" fill={PAL.orangeDark} opacity="0.55" />
    {/* Mountain (large) */}
    <path d="M 0 130 L 90 30 L 175 130 Z" fill={PAL.brown} />
    <path d="M 50 80 L 90 30 L 130 80 L 100 100 L 70 95 Z" fill={PAL.brownDeep} opacity="0.4" />
    {/* Torah scroll — floating in clouds at peak */}
    <g transform="translate(90, 30)">
      {/* Left handle */}
      <circle cx="-22" cy="-12" r="5" fill={PAL.brown} />
      <rect x="-24" y="-22" width="4" height="20" fill={PAL.brown} />
      <circle cx="-22" cy="-22" r="3.5" fill={PAL.gold} />
      {/* Right handle */}
      <circle cx="22" cy="-12" r="5" fill={PAL.brown} />
      <rect x="20" y="-22" width="4" height="20" fill={PAL.brown} />
      <circle cx="22" cy="-22" r="3.5" fill={PAL.gold} />
      {/* Scroll body */}
      <rect x="-20" y="-22" width="40" height="20" rx="2" fill={PAL.cream} stroke={PAL.brown} strokeWidth="1.4" />
      {/* Text lines */}
      <line x1="-15" y1="-17" x2="15" y2="-17" stroke={PAL.brown} strokeWidth="0.8" />
      <line x1="-15" y1="-13" x2="13" y2="-13" stroke={PAL.brown} strokeWidth="0.8" />
      <line x1="-15" y1="-9" x2="15" y2="-9" stroke={PAL.brown} strokeWidth="0.8" />
    </g>
    {/* Cloud at peak */}
    <ellipse cx="90" cy="38" rx="38" ry="6" fill={PAL.cream} opacity="0.5" />
    {/* Ground */}
    <rect x="0" y="125" width="240" height="15" fill={PAL.brownDeep} />
  </Frame>
);

// 1:2 — Three Pillars (world stands on three things)
const IllThreePillars = () => (
  <Frame>
    {/* Sky band */}
    <rect x="0" y="0" width="240" height="140" fill="none" />
    {/* Top architrave */}
    <rect x="40" y="32" width="160" height="10" rx="2" fill={PAL.brown} />
    <rect x="36" y="38" width="168" height="6" fill={PAL.brownDeep} />
    {/* Three columns */}
    {[60, 116, 172].map((x, i) => (
      <g key={i}>
        <rect x={x - 4} y="42" width="32" height="6" fill={PAL.brown} />
        <rect x={x} y="48" width="24" height="62" fill={PAL.cream} stroke={PAL.brown} strokeWidth="1.6" />
        {/* Fluting */}
        <line x1={x + 7} y1="50" x2={x + 7} y2="108" stroke={PAL.brown} strokeWidth="0.8" opacity="0.4" />
        <line x1={x + 12} y1="50" x2={x + 12} y2="108" stroke={PAL.brown} strokeWidth="0.8" opacity="0.4" />
        <line x1={x + 17} y1="50" x2={x + 17} y2="108" stroke={PAL.brown} strokeWidth="0.8" opacity="0.4" />
        {/* Base */}
        <rect x={x - 4} y="110" width="32" height="6" fill={PAL.brown} />
      </g>
    ))}
    {/* Ground */}
    <rect x="0" y="116" width="240" height="24" fill={PAL.brownDeep} />
    <rect x="0" y="116" width="240" height="3" fill={PAL.brown} />
  </Frame>
);

