// Sparkle for any mishnah without illustration
const IllSparkle = () => (
  <Frame>
    {[40, 100, 160, 200].map((x, i) => {
      const y = [50, 75, 50, 90][i];
      const r = [10, 16, 12, 8][i];
      const c = [PAL.sun, PAL.orange, PAL.rose, PAL.plum][i];
      return <polygon key={i}
        points={`${x},${y-r} ${x+r*0.3},${y-r*0.3} ${x+r},${y} ${x+r*0.3},${y+r*0.3} ${x},${y+r} ${x-r*0.3},${y+r*0.3} ${x-r},${y} ${x-r*0.3},${y-r*0.3}`}
        fill={c} stroke={PAL.brown} strokeWidth="1" />;
    })}
    <text x="120" y="130" textAnchor="middle" fontFamily="var(--mono)" fontSize="9" fill={PAL.brown}>more to come</text>
  </Frame>
);

const ILLUSTRATIONS = {
  1: { name: "Moshe at Sinai", Component: IllSinai, url: "data:image/png;base64,", credit: "Custom illustration" },
  2: { name: "Three Pillars", Component: IllThreePillars, url: "data:image/png;base64,", credit: "Custom illustration" },
  3: { name: "Serve from Love", Component: IllHeart, url: "data:image/png;base64,", credit: "Custom illustration" },
  4: { name: "House of Wisdom", Component: IllHouse, url: "data:image/png;base64,", credit: "Custom illustration" },
  5: { name: "Open House", Component: IllWelcome, url: "data:image/png;base64,", credit: "Custom illustration" },
  6: { name: "Acquire a Friend", Component: IllFriends, url: "data:image/png;base64,", credit: "Custom illustration" },
  7: { name: "Shield from Harm", Component: IllShield },
  8: { name: "Scales of Justice", Component: IllScales },
  9: { name: "Investigate Truth", Component: IllMagnify },
  10: { name: "Love of Work", Component: IllWork },
  11: { name: "Careful Words", Component: IllSpeak },
  12: { name: "Dove of Peace", Component: IllDove },
  13: { name: "Humility", Component: IllHumility },
  14: { name: "Now! The Time Is", Component: IllNow },
  15: { name: "Make Torah Fixed", Component: IllBooks },
  16: { name: "Teacher & Student", Component: IllTeacher },
  17: { name: "Silence is Gold", Component: IllSilence },
  18: { name: "Justice · Truth · Peace", Component: IllThreeJTP },
};

const KidsIllustration = ({ mishnahNum }) => {
  const [imgFailed, setImgFailed] = React.useState(false);
  React.useEffect(() => { setImgFailed(false); }, [mishnahNum]);
  const entry = ILLUSTRATIONS[mishnahNum];
  if (!entry) return <IllSparkle />;
  if (entry.url && !imgFailed) {
    return <img src={entry.url} alt={entry.name} className="kids-illu-img" loading="lazy" onError={() => setImgFailed(true)} />;
  }
  const C = entry.Component;
  return <C />;
};

window.KidsIllustration = KidsIllustration;
window.ILLUSTRATIONS = ILLUSTRATIONS;

export { Frame, ILLUSTRATIONS, IllBooks, IllDove, IllFriends, IllHeart, IllHouse, IllHumility, IllMagnify, IllNow, IllScales, IllShield, IllSilence, IllSinai, IllSparkle, IllSpeak, IllTeacher, IllThreeJTP, IllThreePillars, IllWelcome, IllWork, KidsIllustration, PAL };
